style.css:
@-moz-document domain("www.youtube.com") {
/* Backgrounds */
  ytd-app, ytd-masthead, ytd-page-manager, tp-yt-app-drawer, ytd-mini-guide-renderer,
  ytd-guide-renderer, #guide, #contentContainer, #container, html, body {
    background-color: #0d1b2a !important;
    color: #ffffff !important;
  }

  /* Sidebar */
  ytd-guide-entry-renderer, ytd-guide-section-renderer {
    background-color: #1b263b !important;
  }

  /* Top bar */
  ytd-masthead {
    background-color: #1e2a38 !important;
    border-bottom: 1px solid #415a77 !important;
  }

  /* Video thumbnails + cards */
  ytd-rich-grid-media, ytd-video-renderer, ytd-grid-video-renderer {
    background-color: #1e2a38 !important;
    border-radius: 8px !important;
    box-shadow: 0 0 10px rgba(0, 0, 50, 0.2);
    margin-bottom: 10px;
  }

  /* Texts */
  yt-formatted-string, .title, h1, h2, h3, h4, a {
    color: #e0e1dd !important;
  }

  /* Hover effects */
  a:hover, yt-formatted-string:hover {
    color: #a3cef1 !important;
  }

  /* Search box */
  #search-form, #search-input {
    background-color: #415a77 !important;
    color: white !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 10px;
  }

  ::-webkit-scrollbar-track {
    background: #0d1b2a;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #415a77;
    border-radius: 10px;
  }
}
